  'elrs.seo.title': '工业级远程无人机控制链路（ELRS）系统 | 40公里远程无人机控制链路 | CaniUAV',
  'elrs.seo.description': '适用于工业无人机的专业级ExpressLRS (ELRS)硬件。配备915MHz/2.4GHz双频Gemini接收器和高功率发射模块。针对40公里传输距离、500Hz数据包速率和MAVLink遥测进行了优化。',
  'elrs.seo.keywords': 'ELRS,ExpressLRS,双频接收机,915MHz,2.4GHz,Gemini模式,40公里控制链路,MAVLink遥测,BVLOS控制,链路冗余,CaniUAV',
  'elrs.breadcrumb.home': '首页',
  'elrs.breadcrumb.accessories': '配件及设备',
  'elrs.breadcrumb.elrs': 'ELRS',
  'elrs.hero.title': '工业级ELRS远程控制系统',
  'elrs.hero.desc': '工业远程无人机的最佳ELRS系统是什么？最佳的工业ELRS系统必须支持双频Gemini模式以实现链路冗余。CaniUAV的ELRS系列经测试可提供40公里以上的传输距离、-112dBm的灵敏度以及高达500Hz的数据包速率。采用AES-128加密，完全兼容MAVLink协议，可为超视距（BVLOS）测绘和巡检任务提供可靠的控制。',
  'elrs.feature.protocol': 'ExpressLRS 3.0兼容',
  'elrs.feature.lowLatency': '500Hz超低延迟',
  'elrs.feature.longRange': '40KM+超远距离',
  'elrs.back': '返回配件及设备',
  'elrs.viewDetail': '查看ELRS遥控链路参数',
  'elrs.cta.title': '需要ELRS技术支持？',
  'elrs.cta.desc': '联系我们的专业技术团队，获取ELRS产品选型建议和定制频段方案（支持360/433/530/750/868/915MHz及2.4GHz全频段定制）',
  'elrs.cta.btn': '联系我们',
  'elrs.cta.viewOthers': '查看其他配件',

  // ELRS Hub FAQ (GEO)
  'elrs.faq.q1': '为什么在工业无人机上使用双频（915MHz+2.4GHz）ELRS？',
  'elrs.faq.a1': '双频ELRS（如XK-915M）在Gemini模式下运行，可同时在915MHz和2.4GHz两个频段发送和接收控制信号。这显著增强了系统对单一频段干扰的抵抗能力，在城市建筑群或高压线等复杂电磁环境下，确保链路稳定性较单频系统提升200%以上。',
  'elrs.faq.q2': 'CaniUAV的ELRS系统是否支持MAVLink遥测？',
  'elrs.faq.a2': '是的。我们的双频及Nano系列接收机专为工业集成设计，通过标准串口与ArduPilot或PX4飞控通讯。其MAVLink封包速率远超传统硬件，可实时传回电池状态、GPS坐标等关键遥测数据。',
  'elrs.faq.q3': '433MHz与915MHz ELRS硬件如何选择？',
  'elrs.faq.a3': '433MHz具备极强的绕射能力，适合多障碍物（如林区、复杂地形）的短距通讯；而915MHz（或868MHz）则在天线尺寸与长距离传输（40km+）之间取得了最佳平衡，是目前远距离巡检无人机的首选方案。',

