  // ===== FAQ Section =====
  'faq.title': '常见问题',
  'faq.subtitle': '这里整理了客户最常咨询的问题，如果没有找到您需要的答案，请随时联系我们。',
  'faq.general.q1': '长凌科技是做什么的？',
  'faq.general.a1': '长凌科技是专业的工业级无人机配件研发与制造企业，主要产品包括数字图传系统、VTX视频发射器、飞控电调模块、云台吊舱、ELRS遥控器等核心零部件。我们为全球无人机行业提供高品质的配件解决方案。',
  'faq.general.q2': '你们的产品有哪些应用场景？',
  'faq.general.a2': '我们的产品广泛应用于多个领域，包括：航拍摄影、电力线路巡检、物流配送、消防救援、农业植保、测绘测量、环境监测等。无论是专业行业应用还是FPV穿越飞行，都能找到适合的产品。',
  'faq.general.q3': '如何成为你们的代理商或经销商？',
  'faq.general.a3': '欢迎有意向的合作伙伴联系我们的商务团队。我们提供完善的代理政策，包括：区域保护、价格优惠、技术培训、营销支持等。请发送邮件至 market@caniuav.com 或拨打 181-6368-5410 咨询合作详情。',
  'faq.general.q4': '你们提供OEM/ODM定制服务吗？',
  'faq.general.a4': '是的，我们提供全方位的OEM/ODM定制服务。从产品外观设计到功能定制，从小批量试产到大规模量产，我们都能满足客户的个性化需求。定制服务需要根据具体需求评估，请联系我们的技术团队进行详细沟通。',
  'faq.products.q1': '数字图传和模拟图传有什么区别？',
  'faq.products.a1': '数字图传采用数字信号传输，优点是画质清晰（支持1080P/4K）、延迟低（通常<30ms）、抗干扰能力强；模拟图传使用模拟信号，优点是价格实惠、兼容性好、设置简单。对于专业应用和长距离飞行，推荐使用数字图传；对于入门用户和近距离飞行，模拟图传是不错的选择。',
  'faq.products.q2': 'VTX发射器如何选择功率？',
  'faq.products.a2': 'VTX功率选择取决于飞行场景：25mW-200mW适合室内和近距离飞行；400mW-800mW适合户外中等距离；1W-2.5W适合开阔地带远距离飞行；5W以上适合专业长距离应用。注意：大功率VTX需要考虑散热问题，使用前请了解当地无线电法规。',
  'faq.products.q3': 'ELRS和传统2.4GHz遥控有什么优势？',
  'faq.products.a3': 'ELRS（ExpressLRS）是新一代开源遥控协议，主要优势包括：超低延迟（低于5ms）、超远距离（可达100km+）、开源免费、双向数据传输、支持遥测回传。相比传统2.4GHz遥控，ELRS在延迟和距离方面有显著提升，特别适合远距离飞行和专业应用。',
  'faq.products.q4': '云台吊舱如何选择适合的型号？',
  'faq.products.a4': '选择云台需要考虑以下因素：1）载荷需求-确定搭载相机的重量和尺寸；2）稳定精度-专业航拍需要±0.01°级别；3）功能需求-是否需要红外、变焦、激光测距等；4）接口兼容-确保与飞控和相机的接口匹配；5）预算范围-根据应用场景合理配置。',
  'faq.technical.q1': '飞控固件支持哪些版本？',
  'faq.technical.a1': '我们的飞控产品支持多种主流开源固件，包括：Betaflight（推荐4.3以上版本）、iNav（6.0以上）、ArduPilot（4.3以上）。不同固件适合不同应用场景：Betaflight适合FPV穿越和竞速；iNav适合GPS飞行和自主导航；ArduPilot适合专业行业应用。',
  'faq.technical.q2': '图传和遥控信号会互相干扰吗？',
  'faq.technical.a2': '合理的频率规划可以避免干扰。建议配置：遥控使用2.4GHz ELRS，图传使用5.8GHz；或遥控使用915MHz/868MHz ELRS，图传使用2.4GHz。避免遥控和图传使用相同频段。另外，天线布局和功率设置也会影响干扰程度，请参考产品手册进行优化。',
  'faq.technical.q3': '产品支持哪些通信协议？',
  'faq.technical.a3': '我们的产品支持多种通信协议：遥控支持ELRS、CRSF、SBUS、PPM等；图传支持HDMI、AV、USB等视频接口；数据链路支持MAVLink、MSP等协议。具体协议支持请查看各产品规格说明。',
  'faq.technical.q4': '如何进行固件升级？',
  'faq.technical.a4': '大部分产品支持USB或无线方式进行固件升级。具体步骤：1）下载最新固件和升级工具；2）连接设备到电脑；3）运行升级程序；4）等待升级完成。升级前请备份当前配置，升级过程中请勿断电。详细教程请访问我们的技术支持页面。',
  'faq.purchase.q1': '如何购买你们的产品？',
  'faq.purchase.a1': '您可以通过以下渠道购买：1）直接联系我们的销售团队（电话：181-6368-5410）；2）通过授权经销商购买；3）大额订单可以签订合作协议。我们支持银行转账、信用证等多种付款方式，具体请与销售人员沟通。',
  'faq.purchase.q2': '产品有保修吗？保修期多长？',
  'faq.purchase.a2': '我们所有产品均提供质量保修：标准产品保修期为12个月，从购买日期起算；部分产品提供18个月或24个月延长保修。保修范围包括非人为因素导致的产品故障，不包括人为损坏、改装、超规格使用等情况。',
  'faq.purchase.q3': '支持海外发货吗？',
  'faq.purchase.a3': '是的，我们支持全球发货。常用快递包括DHL、FedEx、UPS等国际快递，也支持空运和海运。运费根据目的地和包裹重量计算，通常3-7个工作日可送达主要国家。大额订单可以协商运费优惠。',
  'faq.purchase.q4': '批量采购有优惠吗？',
  'faq.purchase.a4': '是的，批量采购享有阶梯价格优惠。订购数量越大，单价越优惠。具体优惠幅度请联系销售团队。此外，我们还为长期合作伙伴提供账期支持、优先发货、专属技术支持等增值服务。',

