  // Water Application Page - 智慧水利无人机解决方案
  'water.seo.title': '智慧水利无人机解决方案 | 50km超视距河道大坝巡检',
  'water.seo.desc': 'CANI长凌科技工业级无人机智慧水利解决方案，50km+超视距河道巡查、AI非法采砂识别、厘米级三维大坝健康监测，搭载高清数字图传与热成像技术。',
  'water.seo.keywords': '智慧水利无人机,河道巡检无人机,水库大坝监测,超视距BVLOS巡查,非法采砂监控,防汛无人机,数字图传,水利行业解决方案',
  'water.badge': '智慧水利解决方案',
  'water.title': '用于智慧水资源管理的智能无人机遥感网络',
  'water.hero': '传统水利巡检依赖人工步行或船只，效率低且存在巨大的数据盲区。CANI（长凌科技）凭借15年工业级研发积累，构建"空天地"一体化无人机监测网。通过将高清数字图传与AI边缘计算深度融合，协助管理部门实现从"被动响应"到"精准预警"的水务数字化升级。',

  'water.pain.title': '现代水文监测的核心挑战',
  'water.pain.terrain.title': '地形障碍',
  'water.pain.terrain.desc': '众多淤地坝、溢洪道位于深山峡谷，人工巡检面临跌落或落石等安全风险，部分区域甚至无法到达。',
  'water.pain.delay.title': '数据延迟',
  'water.pain.delay.desc': '传统民用系统难以在10km以上稳定传输1080P高清画面，导致事故现场指挥决策严重滞后。',
  'water.pain.manual.title': '人工低效',
  'water.pain.manual.desc': '人工河湖长制巡查周期长，难以实时发现非法排污和采砂等违法违规行为，管理存在大量盲区。',

  'water.scenarios.title': '全场景业务覆盖',
  'water.scene1.title': '自动化河道巡查与AI污染检测',
  'water.scene1.desc': '利用搭载AI引导模块的无人机，系统可自主规划航迹。通过三光云台自动识别排污口、漂浮垃圾及非法乱占乱建现象。AI识别准确率高达95%以上，经纬度坐标与高清图像通过50km长距离链路实时回传。',
  'water.scene2.title': '50公里超视距反非法采砂监视',
  'water.scene2.desc': '非法采砂常发生在深夜或偏远水域。CANI的高清数字图传系统支持超视距（BVLOS）作业，即使在电磁干扰严重的复杂河道环境中，也能保证1080P/60fps取证画面不中断，解决信号丢失的行业瓶颈。',
  'water.scene3.title': '水库大坝健康状况及渗漏监测',
  'water.scene3.desc': '结合热成像技术与RTK定位，无人机可对坝体进行厘米级三维建模。系统能实时探测坝体渗漏产生的温差异常，及早识别管涌、裂隙及结构侵蚀风险，确保基础设施安全运行。',

  'water.vtx.link': '探索数字图传技术参数 →',

  'water.adv.title': '专为关键任务而设计',
  'water.adv.range.title': '50km+长距离传输',
  'water.adv.range.desc': '搭载自主研发的数字图传系统，打破视距限制，覆盖广阔水域的无盲区监控需求。',
  'water.adv.latency.title': '低延迟指挥控制',
  'water.adv.latency.desc': '<200ms端到端延迟，确保在近坝危险区域作业时具备良好的操控实时性。',
  'water.adv.standard.title': '全球安全标准',
  'water.adv.standard.desc': '产品符合NDAA、CE和FCC标准，满足全球政企客户对数据主权和合规性的要求。',

  'water.faq.title': '常见问题',
  'water.faq.q1': 'CANI无人机可以在高湿度水利环境下长期作业吗？',
  'water.faq.a1': '是的，我们的组件采用工业级IP55防风雨密封和防腐蚀涂层，专为水库和潮湿河流流域的全天候水文监测而设计，确保在高湿度、盐雾等恶劣环境下稳定运行。',
  'water.faq.q2': '数字图传系统对河流巡检有什么实际好处？',
