  // Transportation Monitoring Solution Page - 智慧交通解决方案
  'transport.seo.title': '智慧交通无人机解决方案 | 高速公路与桥梁巡检 | CANI长凌科技',
  'transport.seo.desc': '面向高速公路与桥梁管理的工业无人机综合解决方案。搭载50km超远距1080p视频回传、AI自主车辆追踪模块及毫米级精度桥梁结构健康监测（SHM）系统。',
  'transport.seo.keywords': '高速公路监控无人机,桥梁结构检测UAV,交通事故管理,BVLOS道路巡逻,GPS拒止导航',
  'transport.badge': '智慧交通解决方案',
  'transport.title': '面向智能交通和基础设施管理的自主无人机解决方案',
  'transport.hero': '随着2026年全球智慧交通系统（ITS）向数字化、无人化演进，传统路政巡逻与人工桥梁检测已无法满足对效率和安全性的严格要求。CANI利用先进的超视距（BVLOS）传输技术与边缘AI识别系统，为高速公路路网监测与桥梁实时健康管理提供"数字化天眼"。我们的方案旨在将事故响应时间缩短35%，桥梁常规检测成本降低40%。',
  'transport.pain.title': '现代交通运营中的监控漏洞',
  'transport.pain.delay.title': '响应延迟',
  'transport.pain.delay.desc': '在突发交通事故或严重拥堵时，地面巡逻车往往受困于车流，无法第一时间获取现场全景图像。',
  'transport.pain.blind.title': '结构盲点',
  'transport.pain.blind.desc': '特大桥的底部支座、悬索节点以及隧道出口周边，是人眼和固定摄像头难以覆盖的监控盲区。',
  'transport.pain.signal.title': '通信壁垒',
  'transport.pain.signal.desc': '山区高速或密集城市高层环境存在严重信号遮挡，传统民用图传系统在5公里范围外即会出现丢包或黑屏。',
  'transport.scenarios.title': '全场景巡检与监测',
  'transport.scene1.title': '高速公路自动巡逻及交通流量分析',
  'transport.scene1.desc': '搭载CANI高清数字图传系统，单架次巡检无人机的有效指挥半径提升至50km以上，彻底解决长距离路网监管中"看得见但传不回"的痛点。集成AI引导模块，系统可执行自主车辆统计、平均车速测算及逆行/违停自动取证。在120km/h行进速度下，车辆识别准确率达91.8%，F1分数达90.5%。',
  'transport.scene2.title': '桥梁结构健康监测（SHM）',
  'transport.scene2.desc': '传统桥梁检测需封锁车道并使用昂贵的桥梁检测车。CANI方案利用具备GPS-Denied（无GPS环境）导航能力的无人机，实现不中断交通的精准作业。搭载45MP高分辨率传感器，可生成亚毫米级正射图像，自动识别混凝土剥落、露筋及0.2mm级别的结构裂缝。利用红外传感器监测路面坑洞及细微积水，热成像结构检测准确率高达95.12%。',
  'transport.vtx.link': '探索50km超远距图传系统',
  'transport.adv.title': '专为关键任务基础设施而设计',
  'transport.adv.range.title': '50公里超稳定回传',
  'transport.adv.range.desc': '先进的射频放大技术保证在高架立交、基站密集区等复杂电磁环境下，视频流仍保持1080P/60fps稳定传输。',
  'transport.adv.edge.title': 'AI边缘计算',
  'transport.adv.edge.desc': '无需昂贵的云端处理，AI模块可在机载端完成违章分析，仅回传关键预警数据，节省80%带宽压力。',
  'transport.adv.reliable.title': '全天候可靠性',
  'transport.adv.reliable.desc': '硬件采用工业级IP55防护等级及防腐蚀涂层，确保在沿海大桥高盐雾环境或40℃高温路面下持续作业。',
  'transport.faq.title': '常见问题',
  'transport.faq.q1': 'CANI无人机在没有GPS的情况下，能否在桥面下保持精确飞行？',
  'transport.faq.a1': '是的。对于桥底或隧道等GPS信号受限的环境，我们的系统采用基于视觉的导航和IMU传感器融合技术，确保在没有卫星信号的情况下实现稳定悬停和亚厘米级路径跟踪。',
  'transport.faq.q2': '数字图传如何应对山区高速公路上的信号遮挡？',
  'transport.faq.a2': '高清数字图传提供了卓越的链路预算。结合定向地面天线，即使在山区道路网络中常见的地形障碍和多径干扰情况下，也能保持稳定的高清视频信号传输。',
  'transport.cta.title': '获取智慧交通解决方案',
  'transport.cta.subtitle': '联系我们的专业团队，获取交通行业无人机应用方案及投资回报分析',
  'transport.cta.btn': '立即咨询',
  'transport.whitepaper.btn': '下载智慧交通方案白皮书',

