  'softwarePage.management.faq.q1': '长凌管理平台如何实现DJI飞行日志的自动同步？',
  'softwarePage.management.faq.a1': '平台通过DJI Cloud API与MSDK接口自动采集每次飞行的起降时间、GPS轨迹、遥测参数及异常事件日志。数据上传后自动加密存储并生成不可篡改的审计链，确保满足FAA Part 107与EASA的记录保存要求。同时支持PX4和ArduPilot飞控的日志导入。',
