  // GroundStation FAQ
  'softwarePage.groundStation.faq.title': '常见问题',
  'softwarePage.groundStation.faq.q1': '长凌GCS支持哪些无人机协议？',
  'softwarePage.groundStation.faq.a1': '长凌GCS完整支持MAVLink v2和STANAG 4586两大国际标准协议，可兼容PX4、ArduPilot及所有符合MAVLink标准的飞控系统，同时满足NATO军事级互操作性要求。',
  'softwarePage.groundStation.faq.q2': 'AES-256加密和后量子加密（PQC）有什么区别？',
  'softwarePage.groundStation.faq.a2': 'AES-256-GCM是当前最高级别的对称加密标准，广泛应用于军事通信。后量子加密（PQC）则是为抵御未来量子计算机攻击而设计的新一代加密算法，长凌GCS同时集成两者，确保数据在当前和未来均安全无虞。',
  'softwarePage.groundStation.faq.q3': '系统能否在完全无网络的环境下工作？',
  'softwarePage.groundStation.faq.a3': '可以。长凌GCS支持预先导入离线3D地图数据，在完全断网或信号干扰环境下依然能执行完整的航线规划、任务编排与飞行控制，确保电力巡检、应急救援等关键任务的连续性。',
  'softwarePage.groundStation.faq.q4': '长凌GCS最多可同时控制多少架无人机？',
  'softwarePage.groundStation.faq.a4': '长凌GCS支持多机协同编队任务，单个地面站可同时监控和指挥多架无人机执行BVLOS超视距任务。具体同时控制数量取决于数据链路带宽和任务复杂度，典型工业场景下支持5-20架的编队协同。',

