  'softwarePage.swarm.faq.title': '集群控制技术FAQ',
  'softwarePage.swarm.faq.q1': 'sMatrix边缘计算模块的核心优势是什么？',
  'softwarePage.swarm.faq.a1': 'sMatrix是长凌自研的机载边缘计算模块，每架无人机搭载独立AI决策单元，实现去中心化的集群协同。即使与地面站通信中断，机群仍可自主维持编队、避障和任务执行，大幅提升在复杂电磁环境下的任务可靠性。',
  'softwarePage.swarm.faq.q2': '自动接替系统是如何工作的？',
  'softwarePage.swarm.faq.a2': '当集群中某架无人机因故障或低电量需要退出时，系统会自动从备用机群中调派替代机，无缝接替其任务角色和航线位置，整个过程零人工干预、零任务中断，确保大规模搜救和巡检任务的连续性。',
  'softwarePage.swarm.faq.q3': '系统在GNSS干扰环境下如何保持集群导航？',
  'softwarePage.swarm.faq.a3': '长凌集群系统支持多源融合导航方案，在GNSS信号被干扰或遮挡的环境下，通过视觉惯性导航（VIO）、UWB定位和机间相对定位算法维持编队精度，确保在城市峡谷、室内和电磁干扰场景下的可靠运行。',
  'softwarePage.swarm.faq.q4': '集群地面站最多支持多少架无人机同时编队？',
  'softwarePage.swarm.faq.a4': '长凌Swarm GCS目前支持50架以上无人机的同时编队控制，通过sMatrix边缘计算和Mesh自组网技术实现机群间的低延迟协同。系统架构可扩展至更大规模，适用于无人机灯光表演（500+架）和工业级集群巡检（50-100架）等不同场景。',

