  'softwarePage.pvInspection.advantage.a2.title': '自动机场集成',
  'softwarePage.pvInspection.advantage.a2.desc': '与CANI无人机自动机场深度协同，支持全自主起降、充电与7×24小时任务调度',
  'softwarePage.pvInspection.advantage.a3.title': '超远距数字图传',
