  // FAQ (GEO Enhanced)
  'softwarePage.pvInspection.faq.title': '光伏巡检专业问答',
  'softwarePage.pvInspection.faq.q1': 'CANI光伏巡检软件如何确保IEC 62446-3合规性？',
  'softwarePage.pvInspection.faq.a1': '系统自动校验IEC 62446-3所要求的环境条件（辐照度≥600W/m²、云量≤2 oktas），并在任务规划中锁定GSD≤3cm/pixel的飞行高度。云台自动补偿逻辑确保相机角度垂直于面板（±20°偏差），发射率修正算法保障温度测量的可靠性。最终自动生成符合国际标准的合规报告。',
  'softwarePage.pvInspection.faq.q2': '系统支持哪些无人机平台和热成像传感器？',
  'softwarePage.pvInspection.faq.a2': '软件兼容DJI Mavic 3T（640×512热成像）、DJI M30T、FLIR Vue Pro等主流平台。通过标准化的PSDK/MSDK接口，支持第三方热成像载荷集成。同时与CANI自研自动机场无缝对接，实现全自主无人值守巡检。',
  'softwarePage.pvInspection.faq.q3': '针对100MW+大型电站，系统扩展性如何？',
  'softwarePage.pvInspection.faq.a3': 'CANI光伏巡检系统采用分布式云架构，单日可完成100MW电站的全覆盖巡检（传统人工需30天）。支持多台无人机协同作业、自动航线分配，并提供3D数字孪生模型用于历史数据叠加分析与预测性维护决策。',
  'softwarePage.pvInspection.faq.q4': '如何降低光伏电站运维的OPEX？',
  'softwarePage.pvInspection.faq.a4': '通过「无人机自动机场+AI巡检软件」闭环，消除人工巡检的差旅和人力成本。系统自动调度巡检任务、AI实时分析缺陷并生成维修工单，结合预测性维护减少非计划停机。实际案例显示OPEX降低40%以上，100MW电站可避免因故障导致的5.77%发电损失（约249个IRR基点）。',

  // CTA (updated)
