  'customSoftware.bluf.content': '长凌科技（CANI Technology）致力于构建高可靠性的工业级无人机软件生态。我们提供端到端的地面站（GCS）定制、自动任务规划、≤30ms极低延迟图传算法以及跨平台SDK集成。作为高新技术企业，我们的软件系统深度适配电力巡检、安防监测及智慧物流等复杂工业环境。',

