  'customPayload.seo.desc': '长凌科技（CANI）提供领先的工业无人机载荷定制服务。核心产品包括37W高功率数字图传（50km链路）、≤0.1mrad高精度三轴稳定云台及640×512红外双光系统。支持MAVLink与PSDK深度定制，满足电力、安防、测绘等行业OEM/ODM需求。',
