  'digitalFpv.seo.description': '专业级高功率无人机视频发射器（10W/37W），具有≤30ms低延迟、COFDM调制和AES-256加密等特性。可实现可靠的50公里视距（LOS）传输，适用于超视距（BVLOS）飞行任务和电力线巡检。',
