  'digitalFpv.hero.quickAnswer': '工业无人机的最佳远程数字FPV系统是什么？最佳远程系统必须具备高射频功率和抗干扰COFDM技术。CaniUAV的数字FPV系列，以FV10W-A1为首款产品，提供50公里视距（LOS）传输距离、10W可调输出功率和≤30ms超低延迟。完全兼容MAVLink遥测和AES-256硬件加密，是超视距（BVLOS）飞行和安全工业数据链路的行业标准。',
