  'digitalFpv.geo.faq.a5': 'FV10W-A1采用AES-256军事级硬件加密标准，配合自适应跳频和80个抗干扰信道，确保视频和遥测数据在传输过程中不被截获或篡改，满足安防和军工级数据安全要求。',
