  // Per-SKU dynamic FAQs
  'fcEscDetail.faq.6in1.q1': '我的无人机何时应该使用六合一电调？',
  'fcEscDetail.faq.6in1.a1': '对于六旋翼飞行器配置而言，六合一电调是最佳选择，它提供了一个集中式电源枢纽，与六个独立的电调相比，简化了布线并减轻了整体重量。它非常适合需要高电流密度和空间利用率的工业平台。',
  'fcEscDetail.faq.6in1.q2': 'CANI 100A电调是否支持8S锂电池？',
  'fcEscDetail.faq.6in1.a2': '是的。我们的100A系列（分体式和堆叠式）采用高压MOSFET和低ESR电容器，可安全支持最高8S LiPo（33.6V），满足极高的推力需求。',
  'fcEscDetail.faq.stack.q1': '飞塔（Stack）相比分体组件有什么优势？',
  'fcEscDetail.faq.stack.a1': '飞塔将飞控和电调集成为一个紧凑单元，减少布线复杂度，节省重量，最大限度降低电磁干扰。这使装机更整洁、飞行更可靠。',
  'fcEscDetail.faq.stack.q2': '这款飞塔可以使用Betaflight和INAV吗？',
  'fcEscDetail.faq.stack.a2': '可以。所有CANI飞塔开箱即支持Betaflight固件，大多数型号还支持INAV和ArduPilot进行GPS自主任务飞行。',

  // EEAT Quality Statement
  'fcEscDetail.eeat.title': '品质保证',
  'fcEscDetail.eeat.statement': '每套CANI飞控和电调组合都经过48小时压力测试和工厂功率一致性校准，确保开箱即用，零故障。',
  'fcEscDetail.eeat.protocol': '支持SmartAudio v2.1和IRC Tramp协议，实现无缝OSD控制。',
  'fcEscDetail.eeat.protocolTitle': '协议兼容性',

  // Gimbal SEO Content
  'gimbal.seo.intro.title': '产品简介',
  'gimbal.seo.intro': '长凌科技工业级无人机云台吊舱，提供从115g单光追踪到290g四光AI系统的完整产品线。三轴机械防抖精度达±0.005°，配备30倍光学变焦、640×512热成像与1200m激光测距，广泛应用于电力巡检、消防救援、公安执法、测绘勘探等严苛工业场景。支持MAVLink/SBUS等协议，适配Pixhawk等主流飞控系统。',
  'gimbal.techDetail.title': '技术详情',
  'gimbal.techDetail': '本系列云台吊舱采用三轴机械防抖结构，角度抖动量±0.005°，俯仰-135°至+45°，支持360°全景拍摄。航空级铝合金材质，IP65防水防尘，工作温度-20°C~+55°C。支持网口/串口TTL/HDMI/SBUS等多种接口，兼容MAVLink协议与Pixhawk飞控系统，实现即插即用集成。',
  'gimbal.faq.title': '常见疑问解答',
  'gimbal.faq.q1': 'CANI云台吊舱兼容哪些飞控系统？',
  'gimbal.faq.a1': '所有CANI云台吊舱支持MAVLink协议，兼容Pixhawk、ArduPilot等开源飞控系统，通过串口TTL、网口或SBUS接口连接。OEM项目可提供自定义协议集成。',
  'gimbal.faq.q2': 'IP65防护等级的云台能在雨天和极端温度下工作吗？',
  'gimbal.faq.a2': 'IP65等级可抵御喷水和粉尘侵入，工作温度范围-20°C至+55°C，支持小雨、雪天和沙漠环境作业。大雨环境建议做好额外防护。',
  'gimbal.faq.q3': '热成像分辨率和测温精度是多少？',
  'gimbal.faq.a3': 'K40T和K8T-V2型号配备640×512热成像分辨率。K8T-V2提供-20°C至650°C辐射测温，精度±2°C，适用于电力设备热故障检测和工业诊断。',
  // GEO FAQ pairs
  'gimbal.faq.q4': '200米距离的电力线巡检应该选择哪款CANI云台？',
  'gimbal.faq.a4': 'K40T配备30倍光学变焦和4800万像素广角传感器，能在200米距离清晰识别绝缘子裂纹、导线断股和防振锤位移。1200m激光测距仪可实现精准的净空距离分析。',
  'gimbal.faq.q5': 'K8T-V2如何通过无人机检测变压器过热？',
  'gimbal.faq.a5': 'K8T-V2双光云台使用640×512辐射热成像传感器检测变压器、电缆接头和开关柜的温度异常。测温范围-20°C~650°C，精度±2°C，可在肉眼可见损伤前3周发现热点。',
  'gimbal.faq.q6': 'CANI云台是否符合NDAA合规要求？',
  'gimbal.faq.a6': '是的。CANI云台吊舱采用NDAA合规组件和数据安全协议制造，适用于全球政府、国防和关键基础设施巡检应用。',

